<?php
namespace App\Services;
use Illuminate\Support\Facades\Http;
class GeminiService {public function transcribe(string $mime,string $base64):array{$key=config('services.gemini.key');$model=config('services.gemini.model','gemini-2.5-flash');abort_unless($key,503,'سرویس هوش مصنوعی تنظیم نشده است');$prompt='این ورودی را برای تایپ فارسی پردازش کن. فقط متن فارسی، انگلیسی و عربی را استخراج کن. جدول، نمودار، شکل و فرمول را نپذیر و اگر وجود داشت rejected=true کن. غلط های احتمالی OCR را در issues به صورت word و suggestions بده. page_count را تعداد صفحات یا تصاویر واقعی ورودی در نظر بگیر. خروجی فقط JSON با کلیدهای text,page_count,rejected,issues باشد.';$parts=[['text'=>$prompt]];if($mime==='application/zip'){$zip=new \ZipArchive();$raw=base64_decode($base64,true);$tmp=tempnam(sys_get_temp_dir(),'fz');file_put_contents($tmp,$raw);if($zip->open($tmp)===true){$n=0;for($i=0;$i<$zip->numFiles&&$n<30;$i++){ $name=$zip->getNameIndex($i);$ext=strtolower(pathinfo($name,PATHINFO_EXTENSION));if(in_array($ext,['jpg','jpeg','png','webp'])){$data=$zip->getFromIndex($i);$map=['jpg'=>'image/jpeg','jpeg'=>'image/jpeg','png'=>'image/png','webp'=>'image/webp'];$parts[]=['inline_data'=>['mime_type'=>$map[$ext],'data'=>base64_encode($data)]];$n++;}}$zip->close();}@unlink($tmp);abort_if(count($parts)===1,422,'فایل ZIP شامل تصویر قابل پردازش نیست');}else{$parts[]=['inline_data'=>['mime_type'=>$mime,'data'=>$base64]];}$res=Http::timeout(120)->withHeaders(['x-goog-api-key'=>$key])->post('https://generativelanguage.googleapis.com/v1beta/models/'.$model.':generateContent',['contents'=>[['parts'=>$parts]],'generationConfig'=>['responseMimeType'=>'application/json']]);abort_unless($res->successful(),502,'خطا در پردازش هوش مصنوعی');$text=$res->json('candidates.0.content.parts.0.text','{}');$json=json_decode($text,true);abort_unless(is_array($json),502,'پاسخ نامعتبر هوش مصنوعی');return $json;}}
